contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be > 0");
        require(address(this).balance >= amount, "insufficient balance for deposit");
        require(logAddr != address(0), "log address must not be zero");

        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;

        uint preContractBalance = address(c).balance;
        uint preCallerBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint postContractBalance = address(c).balance;
        uint postCallerBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted
            ? (postContractBalance == preContractBalance && postCallerBalance == preCallerBalance)
            : (postContractBalance == preContractBalance + amount && postCallerBalance == preCallerBalance + amount));
    }

    receive() external payable {}
}

