// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount, address logAddr) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        vm.assume(logAddr != address(0));
        try c.SetLogFile(logAddr) {} catch { return; }
        uint preContractBalance = address(c).balance;
        uint256 preCallerBalance;
        try c.balances(address(this)) returns (uint256 __r) { preCallerBalance = __r; } catch { return; }
        bool reverted;
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint postContractBalance = address(c).balance;
        uint256 postCallerBalance;
        try c.balances(address(this)) returns (uint256 __r) { postCallerBalance = __r; } catch { return; }
        assertTrue(reverted
            ? (postContractBalance == preContractBalance && postCallerBalance == preCallerBalance)
            : (postContractBalance == preContractBalance + amount && postCallerBalance == preCallerBalance + amount));
    }

    function testFuzz_run(uint256 amount, address logAddr) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, logAddr);
    }

    receive() external payable {}
}
